/* Shared monetary assumptions; browser copy is generated by the sync script. */
(function (root, factory) {
  if (typeof module === 'object' && module.exports) module.exports = factory();
  else root.CostModel = factory();
})(typeof globalThis !== 'undefined' ? globalThis : this, function () {
  'use strict';

  // Monetary inputs are SEK/kWh unless explicitly named otherwise. Prices are
  // marginal amounts: fixed subscription fees and demand charges are separate.
  function finite(value, name) {
    if (!Number.isFinite(value)) throw new Error(`${name} must be a finite number`);
    return value;
  }
  function validateCostSettings(settings) {
    if (!settings || typeof settings !== 'object' || Array.isArray(settings))
      throw new Error('Cost settings required');
    const s = {
      energyTaxExVatSekPerKWh: finite(settings.energyTaxExVatSekPerKWh, 'energy tax'),
      gridImportExVatSekPerKWh: finite(settings.gridImportExVatSekPerKWh, 'grid import fee'),
      gridExportBenefitSekPerKWh: finite(
        settings.gridExportBenefitSekPerKWh,
        'grid export benefit',
      ),
      gridExportFeeSekPerKWh: finite(settings.gridExportFeeSekPerKWh ?? 0, 'grid export fee'),
      vatRate: finite(settings.vatRate, 'VAT rate'),
      batteryWearSekPerKWh: finite(settings.batteryWearSekPerKWh ?? 0, 'battery wear'),
    };
    if (
      s.vatRate < 0 ||
      s.vatRate > 1 ||
      Object.entries(s).some(([key, value]) => key !== 'gridExportBenefitSekPerKWh' && value < 0)
    ) {
      throw new Error('Invalid cost settings');
    }
    return s;
  }
  // Tibber consumption total is already VAT-inclusive. Do not add VAT again.
  // Production price is an actual signed payout in SEK/kWh, not a purchase price.
  function calculateMarginalPrices({
    tibberImportInclVatSekPerKWh,
    tibberExportSekPerKWh,
    settings,
  }) {
    const s = validateCostSettings(settings);
    const importPrice = finite(tibberImportInclVatSekPerKWh, 'Tibber import price');
    const exportPrice = finite(tibberExportSekPerKWh, 'Tibber export price');
    return {
      importSekPerKWh:
        importPrice +
        (s.gridImportExVatSekPerKWh +
          (settings.importIncludesEnergyTax ? 0 : s.energyTaxExVatSekPerKWh)) *
          (1 + s.vatRate),
      exportSekPerKWh: exportPrice + s.gridExportBenefitSekPerKWh - s.gridExportFeeSekPerKWh,
      components: {
        tibberImportInclVatSekPerKWh: importPrice,
        gridImportInclVatSekPerKWh: s.gridImportExVatSekPerKWh * (1 + s.vatRate),
        energyTaxInclVatSekPerKWh:
          (settings.importIncludesEnergyTax ? 0 : s.energyTaxExVatSekPerKWh) * (1 + s.vatRate),
        tibberExportSekPerKWh: exportPrice,
        gridExportBenefitSekPerKWh: s.gridExportBenefitSekPerKWh,
        gridExportFeeSekPerKWh: s.gridExportFeeSekPerKWh,
      },
      verified: false,
    };
  }
  function evaluateEnergySlots(slots, priceByTimestamp, settings) {
    validateCostSettings(settings);
    let importKWh = 0,
      exportKWh = 0,
      importCostSek = 0,
      exportRevenueSek = 0;
    if (!Array.isArray(slots) || !slots.length || slots.length > 3072)
      return { status: 'insufficient-data', reason: 'Energy intervals missing or excessive' };
    const seen = new Set();
    for (const slot of slots) {
      if (
        !Number.isSafeInteger(slot?.t) ||
        slot.t < 0 ||
        slot.t % 900000 !== 0 ||
        seen.has(slot.t) ||
        !Number.isFinite(slot?.gridWh) ||
        !Number.isFinite(slot.coverageMs) ||
        slot.coverageMs !== 900000 ||
        (slot.directionalCoverageMs !== undefined && slot.directionalCoverageMs !== slot.coverageMs)
      ) {
        return { status: 'insufficient-data', reason: 'Incomplete grid energy interval' };
      }
      seen.add(slot.t);
      const prices = priceByTimestamp?.[slot.t];
      if (
        !prices ||
        !Number.isFinite(prices.importSekPerKWh) ||
        !Number.isFinite(prices.exportSekPerKWh)
      ) {
        return { status: 'insufficient-data', reason: 'Import or export price missing' };
      }
      // Directional totals avoid pricing the net of import/export within a quarter.
      if (
        !Number.isFinite(slot.importWh) ||
        slot.importWh < 0 ||
        !Number.isFinite(slot.exportWh) ||
        slot.exportWh < 0 ||
        Math.abs(slot.importWh - slot.exportWh - slot.gridWh) > 1e-6
      )
        return {
          status: 'insufficient-data',
          reason: 'Directional grid energy missing or inconsistent',
        };
      importKWh += slot.importWh / 1000;
      exportKWh += slot.exportWh / 1000;
      importCostSek += (slot.importWh / 1000) * prices.importSekPerKWh;
      exportRevenueSek += (slot.exportWh / 1000) * prices.exportSekPerKWh;
    }
    return {
      status: 'provisional',
      importKWh,
      exportKWh,
      importCostSek,
      exportRevenueSek,
      netEnergySek: importCostSek - exportRevenueSek,
      advisoryOnly: true,
    };
  }
  function totalScenarioCost({ energy, demandChargeSek, dischargeKWh, settings }) {
    const s = validateCostSettings(settings);
    if (
      energy?.status !== 'provisional' ||
      !Number.isFinite(demandChargeSek) ||
      !Number.isFinite(dischargeKWh) ||
      dischargeKWh < 0
    )
      return null;
    const wearSek = dischargeKWh * s.batteryWearSekPerKWh;
    return {
      energySek: energy.netEnergySek,
      demandChargeSek,
      wearSek,
      totalSek: energy.netEnergySek + demandChargeSek + wearSek,
      advisoryOnly: true,
    };
  }
  const COST_KEYS = [
    'energyTaxExVatSekPerKWh',
    'gridImportExVatSekPerKWh',
    'gridExportBenefitSekPerKWh',
    'gridExportFeeSekPerKWh',
    'vatRate',
    'batteryWearSekPerKWh',
  ];
  function validateCostContract(input) {
    if (
      !input ||
      input.schema !== 1 ||
      input.currency !== 'SEK' ||
      typeof input.importIncludesEnergyTax !== 'boolean' ||
      typeof input.source !== 'string' ||
      !input.source.trim() ||
      input.source.length > 300 ||
      !/^\d{4}-\d{2}-\d{2}$/.test(input.checkedOn) ||
      !Number.isFinite(Date.parse(input.checkedOn)) ||
      new Date(input.checkedOn).toISOString().slice(0, 10) !== input.checkedOn ||
      !COST_KEYS.every((k) => Number.isFinite(input[k]))
    )
      throw new Error('Fyll i alla kostnader, avtalskälla, kontrolldatum och skatteunderlag.');
    const settings = validateCostSettings(input);
    if (input.importIncludesEnergyTax && settings.energyTaxExVatSekPerKWh !== 0)
      throw new Error('Energiskatt ingår redan i importpriset. Ange tilläggsskatt 0.');
    return {
      schema: 1,
      currency: 'SEK',
      source: input.source.trim(),
      checkedOn: input.checkedOn,
      importIncludesEnergyTax: input.importIncludesEnergyTax,
      ...settings,
    };
  }
  return {
    COST_KEYS,
    validateCostContract,
    validateCostSettings,
    calculateMarginalPrices,
    evaluateEnergySlots,
    totalScenarioCost,
  };
});
